    vals += [10**9, 10**9 - 1, 999999999, 536870912, 536870911]
    for _ in range(15):
        vals.append(rng.randint(0, 10**9))
    for _ in range(10):
        vals.append(rng.randint(0, 1000))
    seen = []
    for v in vals:
        if v not in seen:
            seen.append(v)
    return [str(v) for v in seen]

